  '{0} question is not answered yet': ['{0} प्रश्न का उत्तर अभी नहीं दिया गया', '{0} प्रश्नाचे उत्तर अजून दिलेले नाही', '{0} પ્રશ્નનો જવાબ હજી આપ્યો નથી'],
  '{0} unanswered. You can’t change answers after submitting.': ['{0} अनुत्तरित। जमा करने के बाद उत्तर बदल नहीं सकते।', '{0} अनुत्तरित. सादर केल्यानंतर उत्तरे बदलता येत नाहीत.', '{0} જવાબ વિનાના. સબમિટ કર્યા પછી જવાબો બદલી શકાતા નથી.'],
  'Submitted': ['जमा हुआ', 'सादर झाले', 'સબમિટ થયું'],
  'Scoring happens on the server, so this preview can’t show your real score. Below is how the result page looks, with': ['अंक सर्वर पर दिए जाते हैं, इसलिए यह पूर्वावलोकन आपका असली स्कोर नहीं दिखा सकता। नीचे परिणाम पेज ऐसा दिखता है,', 'गुणांकन सर्व्हरवर होते, त्यामुळे हे पूर्वावलोकन तुमचे खरे गुण दाखवू शकत नाही. खाली निकाल पान असे दिसते,', 'ગુણ સર્વર પર અપાય છે, તેથી આ પૂર્વાવલોકન તમારો સાચો સ્કોર બતાવી શકતું નથી. નીચે પરિણામ પેજ આવું દેખાય છે,'],
  'sample numbers': ['नमूना अंकों के साथ', 'नमुना आकड्यांसह', 'નમૂના આંકડા સાથે'],
